import random

import pygame

pygame.init()

WIDTH, HEIGHT = 800, 600
PADDLE_W, PADDLE_H = 12, 100
PADDLE_MARGIN = 30
BALL_SIZE = 14
PADDLE_SPEED = 7
BALL_SPEED = 6
MAX_BALL_SPEED = 12
WINNING_SCORE = 5
FPS = 60

WHITE = (255, 255, 255)
BLACK = (0, 0, 0)

FONT = pygame.font.SysFont("consolas", 48)
SMALL_FONT = pygame.font.SysFont("consolas", 24)


class Paddle:
    def __init__(self, x):
        self.rect = pygame.Rect(x, HEIGHT // 2 - PADDLE_H // 2, PADDLE_W, PADDLE_H)
        self.score = 0

    def move(self, dy):
        self.rect.y = max(0, min(HEIGHT - PADDLE_H, self.rect.y + dy))

    def draw(self, surface):
        pygame.draw.rect(surface, WHITE, self.rect)


class Ball:
    def __init__(self):
        self.reset(random.choice([-1, 1]))

    def reset(self, direction):
        self.x = WIDTH / 2 - BALL_SIZE / 2
        self.y = HEIGHT / 2 - BALL_SIZE / 2
        self.vx = BALL_SPEED * direction
        self.vy = random.choice([-1, 1]) * random.uniform(1.5, 4.5)

    @property
    def rect(self):
        return pygame.Rect(int(self.x), int(self.y), BALL_SIZE, BALL_SIZE)

    def move(self):
        self.x += self.vx
        self.y += self.vy
        if self.y <= 0:
            self.y = 0
            self.vy = abs(self.vy)
        elif self.y + BALL_SIZE >= HEIGHT:
            self.y = HEIGHT - BALL_SIZE
            self.vy = -abs(self.vy)

    def draw(self, surface):
        pygame.draw.rect(surface, WHITE, self.rect)


def handle_collisions(ball, left, right):
    rect = ball.rect
    if ball.vx < 0 and rect.colliderect(left.rect):
        ball.x = left.rect.right
        ball.vx = min(abs(ball.vx) + 0.4, MAX_BALL_SPEED)
        rel = (rect.centery - left.rect.centery) / (PADDLE_H / 2)
        ball.vy = rel * BALL_SPEED
    elif ball.vx > 0 and rect.colliderect(right.rect):
        ball.x = right.rect.left - BALL_SIZE
        ball.vx = -min(abs(ball.vx) + 0.4, MAX_BALL_SPEED)
        rel = (rect.centery - right.rect.centery) / (PADDLE_H / 2)
        ball.vy = rel * BALL_SPEED


def update_score(ball, left, right):
    if ball.x + BALL_SIZE < 0:
        right.score += 1
        return right
    if ball.x > WIDTH:
        left.score += 1
        return left
    return None


class PongGame:
    def __init__(self):
        self.surface = pygame.display.set_mode((WIDTH, HEIGHT))
        pygame.display.set_caption("Two-Player Pong")
        self.clock = pygame.time.Clock()
        self.reset_game()

    def reset_game(self):
        self.left = Paddle(PADDLE_MARGIN)
        self.right = Paddle(WIDTH - PADDLE_MARGIN - PADDLE_W)
        self.ball = Ball()
        self.message = None

    def handle_input(self):
        keys = pygame.key.get_pressed()
        if keys[pygame.K_w]:
            self.left.move(-PADDLE_SPEED)
        if keys[pygame.K_s]:
            self.left.move(PADDLE_SPEED)
        if keys[pygame.K_UP]:
            self.right.move(-PADDLE_SPEED)
        if keys[pygame.K_DOWN]:
            self.right.move(PADDLE_SPEED)
        return keys

    def update(self, keys):
        if self.message is None:
            self.ball.move()
            handle_collisions(self.ball, self.left, self.right)
            scorer = update_score(self.ball, self.left, self.right)
            if scorer:
                if scorer.score >= WINNING_SCORE:
                    winner = "Player 1 (Left)" if scorer is self.left else "Player 2 (Right)"
                    self.message = f"{winner} wins! Press R to restart, Q to quit"
                else:
                    self.ball.reset(-1 if scorer is self.right else 1)
        else:
            if keys[pygame.K_r]:
                self.reset_game()
            elif keys[pygame.K_q]:
                return False
        return True

    def draw(self):
        self.surface.fill(BLACK)
        pygame.draw.line(self.surface, WHITE, (WIDTH // 2, 0), (WIDTH // 2, HEIGHT), 2)
        self.left.draw(self.surface)
        self.right.draw(self.surface)
        self.ball.draw(self.surface)
        l_text = FONT.render(str(self.left.score), True, WHITE)
        r_text = FONT.render(str(self.right.score), True, WHITE)
        self.surface.blit(l_text, (WIDTH // 4 - l_text.get_width() // 2, 20))
        self.surface.blit(r_text, (WIDTH * 3 // 4 - r_text.get_width() // 2, 20))
        hint = SMALL_FONT.render("Left: W/S    Right: Up/Down    First to %d wins" % WINNING_SCORE, True, WHITE)
        self.surface.blit(hint, (WIDTH // 2 - hint.get_width() // 2, HEIGHT - 34))
        if self.message:
            m_text = SMALL_FONT.render(self.message, True, WHITE)
            self.surface.blit(m_text, (WIDTH // 2 - m_text.get_width() // 2,
                                       HEIGHT // 2 - m_text.get_height() // 2))
        pygame.display.flip()

    def run(self):
        running = True
        while running:
            self.clock.tick(FPS)
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    running = False
            keys = self.handle_input()
            running = self.update(keys) and running
            self.draw()
        pygame.quit()
